parameters.jsCode:
const projectRow = $('Extract Project').first()?.json || {};
const phases = $('Extract Phases').all().map(i => i.json).filter(r => r.phase_number);
const milestones = $('Extract Milestones').all().map(i => i.json).filter(r => r.milestone_code);
const tasks = $('Extract Tasks').all().map(i => i.json).filter(r => r.task_id);

return [{
  json: {
    p_project: projectRow,
    p_phases: phases,
    p_milestones: milestones,
    p_tasks: tasks
  }
}];

